{

"kind": "propose",
"summary": "Liveness probe timeout is too short, causing premature restarts",
"hypotheses": [
    {
        "root_cause_class": "probe_timeout_too_short",
        "summary": "Liveness probe timeout is 1s, but app takes longer to start",
        "supporting": ["probe_kills", "killed_during_startup", "ev-rollout_history"],
        "contradicting": ["probe_timeouts"],
        "missing": ["actual_app_start_latency", "container_logs_tail"],
        "status": "supported"
    },
    {
        "root_cause_class": "probe_too_strict_for_startup",
        "summary": "App starts but probes fail before it's ready",
        "supporting": ["killed_during_startup", "ev-rollout_history"],
        "contradicting": ["crashed_on_its_own"],
        "missing": ["container_logs_tail"],
        "status": "supported"
    }
],
"proposal": {
    "capability": "deployment.set-probes",
    "target": {"group": "apps", "kind": "Deployment", "namespace": "finance", "name": "ledger", "uid": "uid-deployment-ledger"},
    "params": {
        "container": "app",
        "liveness": {
            "timeoutSeconds": 10
        }
    },
    "expected_effect": "Increase liveness probe timeout to match app startup duration",
    "rationale": "Current liveness probe timeout is 1s, but app takes longer to start (killed_during_startup). Increasing timeout to 10s allows app to initialize before probe fails. No evidence of application bugs or dependency failures. Readiness probe should not be adjusted as app is not serving traffic yet.",
    "cited_evidence_ids": ["ev-rollout_history", "ev-pod_states", "ev-target_events"],
    "cited_predicates": ["probe_kills", "killed_during_startup", "crashed_on_its_own"]
}
}
